mapper.select:
select * from article
article_user_id = #{articleUserId}
and ( article_title like concat('%',#{articleTitle},'%') or article_content like concat('%',#{articleContent},'%') or article_summary like concat('%',#{articleSummary},'%') )

select article_user_id ,count(*) as articleCount from article where article_user_id in
#{ids}
group by article_user_id

select category_id as categoryId, count(*) as articleCount from category where category_id in
#{ids}
group by category_id

SELECT DISTINCT , t.tag_id, t.tag_name, t.tag_count, c.category_id, c.category_name, c.category_description, c.category_icon, c.category_parent_id, c.category_order FROM article LEFT JOIN user ON article.article_user_id = user.user_id LEFT JOIN article_tag a_t ON article.article_id = a_t.article_id LEFT JOIN tag t ON a_t.tag_id = t.tag_id LEFT JOIN article_category ac ON article.article_id = ac.article_id LEFT JOIN category c ON ac.category_id = c.category_id WHERE article.article_id IN
#{articleId}
AND ac.category_id = #{categoryId} AND article.article_status = 1 ORDER BY article.article_create_time DESC
